import { CommonModule } from '@angular/common';
import { Component } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, Validators, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { PartyService } from '../../services/party-service';
import { Authservice } from '../../services/authservice';
import { Party } from '../../pages/party/party';
import { NgIf, NgFor } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-party',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule, NgFor],
  templateUrl: './add-party.html',
  styleUrls: ['./add-party.css']
})
export class AddParty {
  partyForm: FormGroup;
  stateControl = new FormControl('');
  
  States = [
    { id: 1, name: 'JAMMU AND KASHMIR' },
    { id: 2, name: 'HIMACHAL PRADESH' },
    { id: 3, name: 'PUNJAB' },
    { id: 4, name: 'CHANDIGARH' },
    { id: 5, name: 'UTTARAKHAND' },
    { id: 6, name: 'HARYANA' },
    { id: 7, name: 'DELHI' },
    { id: 8, name: 'RAJASTHAN' },
    { id: 9, name: 'UTTAR PRADESH' },
    { id: 10, name: 'BIHAR' },
    { id: 11, name: 'SIKKIM' },
    { id: 12, name: 'ARUNACHAL PRADESH' },
    { id: 13, name: 'NAGALAND' },
    { id: 14, name: 'MANIPUR' },
    { id: 15, name: 'MIZORAM' },
    { id: 16, name: 'TRIPURA' },
    { id: 17, name: 'MEGHLAYA' },
    { id: 18, name: 'ASSAM' },
    { id: 19, name: 'WEST BENGAL' },
    { id: 20, name: 'JHARKHAND' },
    { id: 21, name: 'ODISHA' },
    { id: 22, name: 'CHATTISGARH' },
    { id: 23, name: 'MADHYA PRADESH' },
    { id: 24, name: 'GUJARAT' },
    { id: 26, name: 'DADRA AND NAGAR HAVELI AND DAMAN AND DIU' },
    { id: 27, name: 'MAHARASHTRA' },
    { id: 28, name: 'ANDHRA PRADESH(BEFORE DIVISION)' },
    { id: 29, name: 'KARNATAKA' },
    { id: 30, name: 'GOA' },
    { id: 31, name: 'LAKSHWADEEP' },
    { id: 32, name: 'KERALA' },
    { id: 33, name: 'TAMIL NADU' },
    { id: 34, name: 'PUDUCHERRY' },
    { id: 35, name: 'ANDAMAN AND NICOBAR ISLANDS' },
    { id: 36, name: 'TELANGANA' },
    { id: 37, name: 'ANDHRA PRADESH (NEWLY ADDED)' },
    { id: 38, name: 'LADAKH (NEWLY ADDED)' },
  ];

  constructor(
    private fb: FormBuilder,
    private service: PartyService,
    private authService: Authservice,
    private router: Router
  ) {
    this.partyForm = this.fb.group({
      name: ['', Validators.required],
      address: ['', Validators.required],
      GSTIN: ['', Validators.required],
      state: ['', Validators.required],
      stateCode: ['', Validators.required]
    });
  }

  onStateChange(event: Event) {
    const target = event.target as HTMLSelectElement;
    const stateId = Number(target.value);
    const selectedState = this.States.find(s => s.id === stateId);

    if (selectedState) {
      this.partyForm.patchValue({
        state: selectedState.name,
        stateCode: selectedState.id
      });
    }
  }

  onSubmit() {
    console.log('Submit clicked');
    if (this.partyForm.invalid) {
      this.partyForm.markAllAsTouched();
      return;
    }

    console.log('Form value:', this.partyForm.value);

    this.service.CreateParties(this.partyForm.value).subscribe({
      next: () => {
        alert('✅ Party created successfully');
        this.resetForm();
        this.router.navigate(['/party'])
      },
      error: (err) => {
        console.error('❌ Upload failed', err);
        alert(err.error?.message || 'Upload failed. Please try again.');
      }
    });
  }

  private resetForm() {
    this.partyForm.reset();
    this.stateControl.reset();
  }
}
